const page = document.documentElement;
const themeButton = document.querySelector(".theme-toggle");
const languageButton = document.querySelector(".language-toggle");
const languageCode = document.querySelector(".language-code");
const menuButton = document.querySelector(".menu-toggle");
const navigation = document.querySelector(".primary-nav");
const profileButton = document.querySelector(".profile-switch");
const profileImage = document.querySelector(".profile-image");
const profileVideo = document.querySelector(".profile-video");
let currentLanguage = "en";
let alternateProfile = true;
const translatedAttributes = {
  "data-i18n-aria": "aria-label",
  "data-i18n-aria-description": "aria-description",
};

function updateTranslations() {
  const words = translations[currentLanguage];
  const isArabic = currentLanguage === "ar";

  page.lang = currentLanguage;
  page.dir = isArabic ? "rtl" : "ltr";
  document.title = words.title;

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const value = words[element.dataset.i18n];
    if (value) element.textContent = value;
  });

  document.querySelectorAll("[data-i18n-alt]").forEach((element) => {
    const key = element === profileImage && alternateProfile
      ? "avatarAltAlt"
      : element.dataset.i18nAlt;
    if (words[key]) element.alt = words[key];
  });

  Object.entries(translatedAttributes).forEach(([dataAttribute, attribute]) => {
    document.querySelectorAll(`[${dataAttribute}]`).forEach((element) => {
      const value = words[element.getAttribute(dataAttribute)];
      if (value) element.setAttribute(attribute, value);
    });
  });

  languageCode.textContent = isArabic ? "English" : "عربي";
  languageButton.setAttribute("aria-label", words[isArabic ? "languageEnglish" : "languageArabic"]);
  themeButton.setAttribute("aria-label", words[page.dataset.theme === "dark" ? "themeLight" : "themeDark"]);
  menuButton.setAttribute("aria-label", navigation.classList.contains("is-open") ? words.closeMenu : words.openMenu);
  profileButton.setAttribute("aria-label", words.changeImage);
}

themeButton.addEventListener("click", () => {
  page.dataset.theme = page.dataset.theme === "dark" ? "light" : "dark";
  try { localStorage.setItem("portfolio-theme", page.dataset.theme); } catch { }
  updateTranslations();
});
try {
  const savedTheme = localStorage.getItem("portfolio-theme");
  if (savedTheme === "light" || savedTheme === "dark") page.dataset.theme = savedTheme;
} catch { }
languageButton.addEventListener("click", () => {
  currentLanguage = currentLanguage === "en" ? "ar" : "en";
  updateTranslations();
});
profileButton.setAttribute("aria-pressed", "true");
profileButton.addEventListener("click", async () => {
  alternateProfile = !alternateProfile;
  profileButton.setAttribute("aria-pressed", String(alternateProfile));
  profileImage.hidden = alternateProfile;
  profileVideo.hidden = !alternateProfile;
  if (alternateProfile) {
    try {
      await profileVideo.play();
    } catch (error) {
      console.error("The profile video could not be played:", error);
    }
  } else {
    profileVideo.pause();
    profileVideo.currentTime = 0;
  }
  updateTranslations();
});
menuButton.addEventListener("click", () => {
  const isOpen = navigation.classList.toggle("is-open");
  menuButton.setAttribute("aria-expanded", String(isOpen));
  updateTranslations();
});
navigation.querySelectorAll("a").forEach((link) => link.addEventListener("click", () => {
  navigation.classList.remove("is-open");
  menuButton.setAttribute("aria-expanded", "false");
  updateTranslations();
}));

const marqueeMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
const marqueeTracks = [...document.querySelectorAll(".marquee-window")].map((viewport) => {
  const track = viewport.querySelector(".marquee-track");
  const loop = viewport.querySelector(".marquee-loop");
  const originalList = loop.querySelector(".marquee-items:not([aria-hidden='true'])");
  const state = { viewport, track, loop, originalList, offset: 0, speed: track.classList.contains("marquee-forward") ? 18 : -18, dragging: false, pointerId: null, startX: 0, startOffset: 0, width: 0 };
  function applyOffset() { if (state.width) loop.style.transform = `translate3d(${-state.offset}px, 0, 0)`; }
  function wrapOffset(value) { return ((value % state.width) + state.width) % state.width; }
  function measure() {
    state.width = originalList.getBoundingClientRect().width;
    if (!state.width) return;
    while (!marqueeMotion.matches && loop.scrollWidth < viewport.clientWidth + state.width) {
      const copy = originalList.cloneNode(true);
      copy.setAttribute("aria-hidden", "true");
      copy.querySelectorAll("img").forEach((img) => img.setAttribute("draggable", "false"));
      loop.append(copy);
    }
    state.offset = wrapOffset(state.offset);
    applyOffset();
  }
  measure();
  viewport.querySelectorAll("img").forEach((img) => img.setAttribute("draggable", "false"));
  viewport.addEventListener("pointerdown", (event) => {
    if (event.pointerType === "mouse" && event.button !== 0) return;
    if (!state.width) measure();
    if (!state.width) return;
    state.dragging = true; state.pointerId = event.pointerId; state.startX = event.clientX; state.startOffset = state.offset;
    viewport.classList.add("is-dragging"); viewport.setPointerCapture(event.pointerId);
  });
  viewport.addEventListener("pointermove", (event) => {
    if (!state.dragging || event.pointerId !== state.pointerId) return;
    state.offset = wrapOffset(state.startOffset - (event.clientX - state.startX)); applyOffset();
  });
  function endDrag(event) {
    if (event.pointerId !== state.pointerId) return;
    state.dragging = false; state.pointerId = null; viewport.classList.remove("is-dragging");
  }
  viewport.addEventListener("pointerup", endDrag); viewport.addEventListener("pointercancel", endDrag); viewport.addEventListener("lostpointercapture", endDrag);
  viewport.addEventListener("keydown", (event) => {
    if (!state.width) return;
    if (event.key === "ArrowLeft") state.offset = wrapOffset(state.offset + 60);
    else if (event.key === "ArrowRight") state.offset = wrapOffset(state.offset - 60);
    else if (event.key === "Home") state.offset = 0;
    else if (event.key === "End") state.offset = state.width - 1;
    else return;
    event.preventDefault(); applyOffset();
  });
  state.measure = measure; state.applyOffset = applyOffset; state.wrapOffset = wrapOffset;
  return state;
});
if ("ResizeObserver" in window) {
  const observer = new ResizeObserver(() => marqueeTracks.forEach((item) => item.measure()));
  marqueeTracks.forEach((item) => { observer.observe(item.viewport); observer.observe(item.originalList); });
} else window.addEventListener("resize", () => marqueeTracks.forEach((item) => item.measure()));
let previousFrame = 0;
function moveMarquees(time) {
  if (previousFrame && !marqueeMotion.matches) {
    const elapsed = Math.min(time - previousFrame, 48) / 1000;
    marqueeTracks.forEach((item) => {
      if (item.dragging || !item.width) return;
      item.offset = item.wrapOffset(item.offset + item.speed * elapsed); item.applyOffset();
    });
  }
  previousFrame = time;
  if (!marqueeMotion.matches) requestAnimationFrame(moveMarquees);
}
if (!marqueeMotion.matches) requestAnimationFrame(moveMarquees);
marqueeMotion.addEventListener("change", () => {
  previousFrame = 0;
  if (marqueeMotion.matches) marqueeTracks.forEach((item) => { item.offset = 0; item.applyOffset(); });
  else { marqueeTracks.forEach((item) => item.measure()); requestAnimationFrame(moveMarquees); }
});
document.querySelector("#current-year").textContent = new Date().getFullYear();
updateTranslations();

const contactForm = document.querySelector("#contact-form");
contactForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const formData = new FormData(contactForm);
  const subject = encodeURIComponent(`Portfolio message from ${formData.get("name")}`);
  const body = encodeURIComponent(`Name: ${formData.get("name")}\nEmail: ${formData.get("email")}\n\n${formData.get("message")}`);
  window.location.href = `mailto:abdalzoubi03@gmail.com?subject=${subject}&body=${body}`;
});
